{"source":"def investigate(context, acquire):
    events = context.get('events', [])
    count = 0
    status = 'open'
    pending = []

    def feed(bs):
        nonlocal count, status, pending
        if status != 'open':
            return
        combined = pending + list(bs)
        n = len(combined)
        i = 0
        total = 0
        while i < n:
            b = combined[i]
            if b < 128:
                i += 1
                total += 1
            elif b < 192:
                status = 'error'
                pending = []
                return
            elif b < 224:
