                    return
                if b == 244 and combined[i + 1] > 143:
                    status = 'error'
                    pending = []
                    return
                i += 4
                total += 1
            else:
                status = 'error'
                pending = []
                return
        count += total
        pending = combined[i:]

    def finish():
        nonlocal status, pending
        if status != 'open':
            return
        if len(pending) == 0:
            status = 'finished'
        else:
            status = 'error'
            pending = []

    def reset():
        nonlocal count, status, pending
        count = 0
        status = 'open'
        pending = []

    for event in events:
        op = event.get('op')
        if op == 'feed':
            feed(event.get('bytes', []))
        elif op == 'finish':
            finish()
        elif op == 'reset':
            reset()
    return {'count': count, 'status': status}
